#!/usr/bin/python
import os, sys

base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
document = os.path.join(base, 'document.txt')

for number in range(int(sys.argv[1])):
    f = None
    try:
        f = open(document)
        sys.stdout.write(str(len(f.read())) + '\n')
    finally:
        if f is not None:
            f.close()
